# Simplified coordinator + participant. Real systems fsync WAL; dicts stand in here.
class Participant:
    def __init__(self, name):
        self.name = name
        self.log = {}  # txn_id -> PREPARED | COMMIT | ABORT
        self.locked = set()
    def prepare(self, txn_id, keys):
        if txn_id in self.log:
            return self.log[txn_id]  # idempotent replay
        if not self.can_lock(keys):
            self.log[txn_id] = "ABORT"
            return "NO"
        self.lock(keys)              # hold until decision
        self.wal_write(txn_id, "PREPARED", keys)
        return "YES"
    def decide(self, txn_id, decision):
        # Must be idempotent: coordinator retries until ack.
        if self.log.get(txn_id) == decision:
            return "ACK"
        self.wal_write(txn_id, decision, None)
        if decision == "COMMIT":
            self.apply_staged(txn_id)
        else:
            self.discard_staged(txn_id)
        self.unlock(txn_id)
        return "ACK"
    def recover(self, txn_id, coordinator):
        if self.log.get(txn_id) == "PREPARED":
            # In-doubt: block and poll, never unilaterally abort.
            return coordinator.query_decision(txn_id)
    def wal_write(self, txn_id, state, keys):
        self.log[txn_id] = state  # real code: serialize + fsync first
    def can_lock(self, keys): return True
    def lock(self, keys): pass
    def unlock(self, txn_id): pass
    def apply_staged(self, txn_id): pass
    def discard_staged(self, txn_id): pass
class Coordinator:
    def __init__(self, participants):
        self.participants = participants
        self.log = {}
    def run(self, txn_id, work):
        self.wal_write(txn_id, "BEGIN")
        votes = [p.prepare(txn_id, work[p.name]) for p in self.participants]
        decision = "COMMIT" if all(v == "YES" for v in votes) else "ABORT"
        self.wal_write(txn_id, decision)  # decision durable BEFORE broadcast
        for p in self.participants:
            p.decide(txn_id, decision)  # retry until ACK in real code
        return decision
    def query_decision(self, txn_id):
        return self.log.get(txn_id, "ABORT")  # no decision yet => abort
    def wal_write(self, txn_id, state):
        self.log[txn_id] = state
